/**
 * Service worker — offline support.
 *
 * Hand-written rather than generated by Workbox: the caching needs here are
 * simple, and a build-time plugin would add a dependency plus a generated
 * bundle for behaviour that fits in one readable file.
 *
 * Strategy by resource type:
 *   - Navigations: network-first, falling back to cache, then to the offline
 *     page. Content sites must show fresh pages when online.
 *   - Fingerprinted assets (/_astro/, fonts): cache-first and effectively
 *     permanent — the filename changes whenever the content does.
 *   - Everything else: stale-while-revalidate.
 *
 * Bump CACHE_VERSION to invalidate every cache on the next deploy.
 */

/**
 * Replaced at build time with a content hash (see scripts/stamp-sw.mjs).
 *
 * A hardcoded version never changes between deploys, so the old cache is never
 * discarded and returning visitors keep getting stale HTML — including old
 * markup and old assets — until they manually clear site data.
 */
const CACHE_VERSION = '__BUILD_ID__';
const PRECACHE = `ts-precache-${CACHE_VERSION}`;
const RUNTIME = `ts-runtime-${CACHE_VERSION}`;
const OFFLINE_URL = '/offline/';

/** Shell resources needed for a useful offline experience. */
const PRECACHE_URLS = ['/', '/typing-test/', OFFLINE_URL];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(PRECACHE)
      // Individual failures must not abort the whole install.
      .then((cache) => Promise.allSettled(PRECACHE_URLS.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== PRECACHE && key !== RUNTIME)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

/** Fingerprinted assets can be cached indefinitely. */
function isImmutable(url) {
  return url.pathname.startsWith('/_astro/') || url.pathname.startsWith('/fonts/');
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Never interfere with non-GET or cross-origin requests (including ads).
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(RUNTIME).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(async () => {
          const cached = await caches.match(request);
          return cached ?? (await caches.match(OFFLINE_URL)) ?? Response.error();
        }),
    );
    return;
  }

  if (isImmutable(url)) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            const copy = response.clone();
            caches.open(RUNTIME).then((cache) => cache.put(request, copy));
            return response;
          }),
      ),
    );
    return;
  }

  // Stale-while-revalidate for everything else.
  event.respondWith(
    caches.match(request).then((cached) => {
      const network = fetch(request)
        .then((response) => {
          if (response.ok) {
            const copy = response.clone();
            caches.open(RUNTIME).then((cache) => cache.put(request, copy));
          }
          return response;
        })
        .catch(() => cached ?? Response.error());

      return cached ?? network;
    }),
  );
});
